pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address callerA, address callerB) public {
        vm.assume(callerA != callerB);
        bytes memory encoded = abi.encodeWithSelector(C.owner.selector);
        (bool successA, bytes memory retA) = address(c).staticcall(encoded);
        require(successA, "first call failed");
        vm.prank(callerA);
        (bool success1, bytes memory ret1) = address(c).staticcall(encoded);
        require(success1, "second call failed");
        vm.prank(callerB);
        (bool success2, bytes memory ret2) = address(c).staticcall(encoded);
        require(success2, "third call failed");
        address valA = abi.decode(retA, (address));
        address val1 = abi.decode(ret1, (address));
        address val2 = abi.decode(ret2, (address));
        assertTrue(valA == val1 && val1 == val2);
    }
}

