contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address target, uint256 amount) public {
        vm.assume(target != address(0) && target != address(c) && target != address(this));
        // Perform a transfer to potentially affect state (though name should remain constant)
        vm.prank(target);
        try c.transfer(address(0x1), amount) {} catch {}
        // Assert that name() always returns the constant token name "DCF Token"
        assertTrue(
            keccak256(abi.encodePacked(c.name())) == keccak256(abi.encodePacked("DCF Token"))
        );
    }
}

